Definition gbb_step (p acc ch : Z) : Z := if ((ch <=? p) && (acc <? ch))%Z then ch else acc.
Fixpoint gbb_fold (p acc : Z) (l : list Z) : Z :=
  match l with [] => acc | ch :: l' => gbb_fold p (gbb_step p acc ch) l' end.

